import configparser
import json
import re
import subprocess
import urllib.parse
import urllib.request


def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)


def get_json(url, headers=None):
    request = urllib.request.Request(url, headers=headers or {})
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.load(response)


sab_config = configparser.ConfigParser(interpolation=None)
sab_config.read_string(dexec("sabnzbd", "cat", "/config/sabnzbd.ini"))
sab_key = sab_config["misc"]["api_key"]


def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return get_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))


lidarr_xml = dexec("lidarr", "cat", "/config/config.xml")
lidarr_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lidarr_xml).group(1)
lidarr_headers = {"X-Api-Key": lidarr_key}

queue = sab("queue", limit=200)["queue"]
history = sab("history", limit=300)["history"]
lidarr_queue = get_json(
    "http://172.20.1.25:8686/api/v1/queue?page=1&pageSize=200&includeUnknownArtistItems=true",
    lidarr_headers,
)
lidarr_history = get_json(
    "http://172.20.1.25:8686/api/v1/history?page=1&pageSize=300&sortDirection=descending&sortKey=date",
    lidarr_headers,
)
lidarr_health = get_json("http://172.20.1.25:8686/api/v1/health", lidarr_headers)

sab_queue_fields = ["nzo_id", "filename", "cat", "status", "percentage", "mb", "mbleft", "timeleft", "avg_age", "msg", "unpackopts", "priority"]
sab_history_fields = ["nzo_id", "name", "category", "status", "fail_message", "storage", "bytes", "completed", "download_time", "postproc_time", "url"]
lidarr_queue_fields = ["id", "title", "status", "trackedDownloadStatus", "trackedDownloadState", "statusMessages", "errorMessage", "downloadId", "protocol", "size", "sizeleft", "timeleft", "artist", "album"]
lidarr_history_fields = ["id", "sourceTitle", "eventType", "date", "downloadId", "quality", "data", "artistId", "albumId"]


def pick(item, fields):
    return {field: item.get(field) for field in fields if field in item}


music_history = [
    item
    for item in history.get("slots", [])
    if str(item.get("category", "")).lower() == "music" or item.get("status") != "Completed"
]
recent_lidarr = [
    pick(item, lidarr_history_fields)
    for item in lidarr_history.get("records", [])
    if item.get("eventType") in ("downloadFailed", "downloadFolderImported", "trackFileImported", "trackFileRenamed")
    or item.get("downloadId")
]

print(
    json.dumps(
        {
            "sab_queue_summary": pick(queue, ["status", "speed", "size", "sizeleft", "timeleft", "noofslots", "diskspace1", "diskspace2", "paused"]),
            "sab_queue": [pick(item, sab_queue_fields) for item in queue.get("slots", [])],
            "sab_music_or_failed_history": [pick(item, sab_history_fields) for item in music_history[:100]],
            "lidarr_queue_total": lidarr_queue.get("totalRecords"),
            "lidarr_queue": [pick(item, lidarr_queue_fields) for item in lidarr_queue.get("records", [])],
            "lidarr_recent_relevant_history": recent_lidarr[:120],
            "lidarr_health": lidarr_health,
        },
        indent=2,
        default=str,
    )
)

