import json
import re
import subprocess
import time
import urllib.parse
import urllib.request


def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)


def get_json(url, headers=None):
    request = urllib.request.Request(url, headers=headers or {})
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.load(response)


sab_ini = dexec("sabnzbd", "cat", "/config/sabnzbd.ini")
sab_key = re.search(r"(?m)^api_key\s*=\s*(\S+)", sab_ini).group(1)


def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return get_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))


for attempt in range(6):
    queue = sab("queue", limit=50)["queue"]
    rows = [
        {
            "name": item.get("filename"),
            "status": item.get("status"),
            "percentage": item.get("percentage"),
            "left": item.get("sizeleft"),
            "missing_mb": item.get("mbmissing"),
        }
        for item in queue.get("slots", [])
        if item.get("cat") == "music"
    ]
    print(json.dumps({"time": time.strftime("%FT%TZ", time.gmtime()), "speed": queue.get("speed"), "music": rows}), flush=True)
    if not rows:
        break
    if attempt < 5:
        time.sleep(10)

