import json
import re
import subprocess
import urllib.error
import urllib.parse
import urllib.request


def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)


def request_json(url, headers=None, method="GET"):
    request = urllib.request.Request(url, headers=headers or {}, method=method)
    with urllib.request.urlopen(request, timeout=30) as response:
        body = response.read()
        return json.loads(body) if body else {"http_status": response.status}


sab_ini = dexec("sabnzbd", "cat", "/config/sabnzbd.ini")
sab_key = re.search(r"(?m)^api_key\s*=\s*(\S+)", sab_ini).group(1)


def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return request_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))


failed_ids = {
    "89eb8f90-88e7-48dd-a90f-42709c10e53c",
    "4c44c801-b30f-4db6-ae27-87499cf91d1d",
    "1b544bf0-a441-4cab-9ed2-2eb8b4249603",
    "0999d2f7-8d2d-43e5-8b8c-b935eb220d42",
}
history = sab("history", limit=100)["history"].get("slots", [])
found = {item["nzo_id"]: item for item in history if item.get("nzo_id") in failed_ids}
if set(found) != failed_ids:
    raise RuntimeError(f"Refusing SAB cleanup because exact targets changed: {sorted(found)}")
for download_id, item in found.items():
    if item.get("status") != "Failed" or "requires a password" not in item.get("fail_message", ""):
        raise RuntimeError(f"Refusing SAB cleanup for changed target {download_id}")

lidarr_xml = dexec("lidarr", "cat", "/config/config.xml")
lidarr_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lidarr_xml).group(1)
headers = {"X-Api-Key": lidarr_key}
queue = request_json("http://172.20.1.25:8686/api/v1/queue?page=1&pageSize=500&includeUnknownArtistItems=true", headers)
bad_lidarr_ids = {207207223, 1089851581}
lidarr_found = {item["id"]: item for item in queue.get("records", []) if item.get("id") in bad_lidarr_ids}
if set(lidarr_found) != bad_lidarr_ids:
    raise RuntimeError(f"Refusing Lidarr cleanup because exact targets changed: {sorted(lidarr_found)}")
for queue_id, item in lidarr_found.items():
    if item.get("trackedDownloadState") != "importFailed" or item.get("protocol") != "usenet":
        raise RuntimeError(f"Refusing Lidarr cleanup for changed target {queue_id}")

