import collections
import json
import re
import subprocess
import urllib.parse
import urllib.request


def run(*args):
    return subprocess.check_output(args, text=True, stderr=subprocess.STDOUT)


def dexec(container, *args):
    return run("docker", "exec", container, *args)


def get_json(url, headers=None):
    request = urllib.request.Request(url, headers=headers or {})
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.load(response)


sab_ini = dexec("sabnzbd", "cat", "/config/sabnzbd.ini")
sab_key = re.search(r"(?m)^api_key\s*=\s*(\S+)", sab_ini).group(1)


def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return get_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))


lidarr_xml = dexec("lidarr", "cat", "/config/config.xml")
lidarr_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lidarr_xml).group(1)
lidarr_headers = {"X-Api-Key": lidarr_key}
lidarr_queue = get_json(
    "http://172.20.1.25:8686/api/v1/queue?page=1&pageSize=500&includeUnknownArtistItems=true",
    lidarr_headers,
)
lidarr_history = get_json(
    "http://172.20.1.25:8686/api/v1/history?page=1&pageSize=5000&sortDirection=descending&sortKey=date",
    lidarr_headers,
)

sab_queue = sab("queue", limit=200)["queue"].get("slots", [])
ids = {item["nzo_id"] for item in sab_queue}

scalar_queue = []
for item in sab_queue:
    scalar_queue.append({key: value for key, value in item.items() if isinstance(value, (str, int, float, bool)) and key not in {"api_key"}})

lidarr_usenet = []
for item in lidarr_queue.get("records", []):
    if item.get("protocol") == "usenet":
        lidarr_usenet.append(
            {
                key: item.get(key)
                for key in ("id", "title", "status", "trackedDownloadStatus", "trackedDownloadState", "statusMessages", "errorMessage", "downloadId", "size", "sizeleft", "timeleft")
                if key in item
            }
        )

matched_history = []
for item in lidarr_history.get("records", []):
    if item.get("downloadId") in ids:
        matched_history.append(
            {
                "sourceTitle": item.get("sourceTitle"),
                "eventType": item.get("eventType"),
                "date": item.get("date"),
                "downloadId": item.get("downloadId"),
                "data": {key: value for key, value in item.get("data", {}).items() if key in ("downloadClient", "message", "size", "age", "publishedDate", "releaseSource")},
            }
        )

aggregate = collections.Counter(
    (item.get("protocol"), item.get("status"), item.get("trackedDownloadState"), item.get("trackedDownloadStatus"))
    for item in lidarr_queue.get("records", [])
)

files = dexec(
    "sabnzbd",
    "find",
    "/data/usenet/incomplete",
    "-mindepth", "1",
    "-maxdepth", "2",
    "-printf", "%TY-%Tm-%TdT%TH:%TM:%TS %y %s %p\\n",
)

logs = run("docker", "logs", "sabnzbd", "--since", "72h")
needles = ["pause", "warning", "error", "missing", "article", "disk"] + [item["filename"].split("-")[0] for item in sab_queue]
log_matches = [line for line in logs.splitlines() if any(needle.lower() in line.lower() for needle in needles)]

print(json.dumps({
    "sab_queue_full_scalars": scalar_queue,
    "lidarr_queue_aggregate": [{"group": list(key), "count": count} for key, count in aggregate.items()],
    "lidarr_usenet_queue": lidarr_usenet,
    "lidarr_history_for_sab_queue": matched_history,
    "incomplete_files": files.splitlines(),
    "sab_log_matches": log_matches[-300:],
}, indent=2))

