import collections
import http.cookiejar
import json
import os
import re
import subprocess
import urllib.parse
import urllib.request


def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)


def get_json(url, headers=None, opener=None):
    request = urllib.request.Request(url, headers=headers or {})
    with (opener or urllib.request).open(request, timeout=30) as response:
        return json.load(response)


lidarr_xml = dexec("lidarr", "cat", "/config/config.xml")
lidarr_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lidarr_xml).group(1)
lidarr_headers = {"X-Api-Key": lidarr_key}
base = "http://172.20.1.25:8686/api/v1"
queue = get_json(base + "/queue?page=1&pageSize=500&includeUnknownArtistItems=true", lidarr_headers)
clients = get_json(base + "/downloadclient", lidarr_headers)

qbit_client = next(item for item in clients if item.get("implementation") == "QBittorrent")
fields = {field["name"]: field.get("value") for field in qbit_client["fields"]}
host = fields.get("host") or "qbittorrent"
port = fields.get("port") or 8080
url_base = str(fields.get("urlBase") or "").strip("/")
qbit_base = f"http://172.20.1.23:{port}"
if url_base:
    qbit_base += "/" + url_base

cookie_jar = http.cookiejar.CookieJar()
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cookie_jar))
login_data = urllib.parse.urlencode({"username": fields.get("username", ""), "password": fields.get("password", "")}).encode()
login_request = urllib.request.Request(qbit_base + "/api/v2/auth/login", data=login_data)
with opener.open(login_request, timeout=30) as response:
    login_result = response.read().decode().strip()
if login_result != "Ok.":
    raise RuntimeError("qBittorrent login failed")

torrents = get_json(qbit_base + "/api/v2/torrents/info", opener=opener)
torrent_by_hash = {item["hash"].upper(): item for item in torrents}

records = []
groups = collections.Counter()
for item in queue.get("records", []):
    if item.get("protocol") != "torrent":
        continue
    reasons = []
    for message in item.get("statusMessages", []):
        reasons.append(message.get("title", ""))
        reasons.extend(message.get("messages", []))
    normalized = []
    for reason in reasons:
        if reason.startswith("Album match is not close enough"):
            normalized.append("Album match below threshold")
        elif reason.startswith("Found matching series via grab history"):
            normalized.append("Matched via grab history")
        elif reason and reason not in normalized:
            normalized.append(reason)
    for reason in set(normalized):
        groups[reason] += 1
    torrent = torrent_by_hash.get(str(item.get("downloadId", "")).upper(), {})
    records.append({
        "lidarrId": item.get("id"),
        "downloadId": item.get("downloadId"),
        "title": item.get("title"),
        "trackedState": item.get("trackedDownloadState"),
        "trackedStatus": item.get("trackedDownloadStatus"),
        "reasons": normalized,
        "qbit": {key: torrent.get(key) for key in (
            "name", "state", "progress", "size", "amount_left", "added_on", "completion_on",
            "last_activity", "ratio", "category", "tags", "save_path", "content_path",
            "tracker", "num_seeds", "num_leechs", "availability",
        )},
    })

queue_hashes = {str(item.get("downloadId", "")).upper() for item in queue.get("records", []) if item.get("protocol") == "torrent"}
orphaned = [
    {key: item.get(key) for key in ("hash", "name", "state", "progress", "size", "added_on", "completion_on", "last_activity", "ratio", "category", "tags", "save_path", "content_path")}
    for item in torrents
    if item.get("category", "").lower() == "lidarr" and item.get("hash", "").upper() not in queue_hashes
]

print(json.dumps({
    "lidarr_torrent_count": len(records),
    "reason_counts": dict(groups.most_common()),
    "records": records,
    "qbit_lidarr_orphans": orphaned,
}, indent=2))

